<script setup lang="ts">
import {computed} from 'vue';
import {Button} from '@openclaw-plugins/control-ui-kit';
import {taskTime} from '../timing.mjs';
import {statusLabels,activeStatuses,deliveryLabels,time,sessionKey,sessionName,type SessionRow,type SessionList} from './models';
import WorkerMenu from './WorkerMenu.vue';
const props=defineProps<{rows:SessionRow[];list:SessionList|null;loading:boolean;error:string;selectionMode:boolean;checked:Map<string,SessionRow>;deleting:boolean;writable:boolean;menu:string|null;redact:(value:string)=>string;now:number}>();
const emit=defineEmits<{choose:[row:SessionRow];toggle:[row:SessionRow];remove:[row:SessionRow];pick:[row:SessionRow];menu:[id:string|null];more:[]}>();
const groups=computed(()=>[['进行中','active'],['历史会话','history'],['状态待确认','unknown']].map(([title,id])=>{const rows=props.rows.filter(row=>(row.status==='unknown'?'unknown':activeStatuses.has(row.status)?'active':'history')===id),total=props.list?.groupCounts?.[id!]??rows.length;return {title,id,rows,total,count:rows.length<total?`${rows.length} / ${total}`:String(total)};}).filter(g=>g.total));
function progress(row:SessionRow){return row.progress&&!['执行已完成','结果已交付','历史任务记录不可用'].includes(row.progress)?props.redact(row.progress):'';}
function delivery(row:SessionRow){return deliveryLabels[row.notificationState??'']??(row.progress==='结果已交付'?'已交付':'');}
</script>
<template>
 <template v-for="group in groups" :key="group.id"><component :is="group.id==='unknown'?'details':'section'" :class="group.id==='unknown'?'cq-disclosure cq-pending-group':'cq-list-group'" :data-fold-key="group.id==='unknown'?'unknown-sessions':undefined"><summary v-if="group.id==='unknown'">{{group.title}} · {{group.count}}</summary><h3 v-else class="cq-group-heading" :title="group.rows.length<group.total?'已加载会话数 / 匹配会话总数':'匹配会话总数'"><span>{{group.title}}</span><span class="cq-group-count">{{group.count}}</span></h3><div class="cq-session-group" :class="{'cq-disclosure-body':group.id==='unknown'}"><p v-if="group.id==='unknown'" class="cq-muted">这些会话的执行状态暂无法核实，不计入已确认的运行任务。</p>
 <article v-for="row in group.rows" :key="sessionKey(row)" class="cq-row" :class="{'cq-row-checked':selectionMode&&checked.has(sessionKey(row))}" :data-record-key="row.topic+':'+(row.executionScope??'legacy')+':'+(row.modelSessionScope??'legacy')">
  <input v-if="selectionMode" type="checkbox" class="cq-session-check" :data-key="sessionKey(row)" :aria-label="redact('选择会话 '+sessionName(row))" :checked="checked.has(sessionKey(row))" :disabled="deleting||row.canDelete!==true" :title="redact(row.deleteReason??'')" @change="emit('toggle',row)">
  <Button variant="ghost" class="cq-row-open ocp:whitespace-normal" :disabled="selectionMode&&(deleting||row.canDelete!==true)" :title="selectionMode&&row.deleteReason?redact(row.deleteReason):undefined" @click="selectionMode?emit('toggle',row):emit('choose',row)"><small v-if="row.model" class="cq-muted">{{redact((row.harness??'codex')+' / '+row.model)}}</small><div class="cq-row-top"><strong :title="redact(row.repository??row.topic)">{{redact(row.projectId?row.projectId+' / '+row.topic:row.topic)}}</strong><span class="cq-state" :class="row.status">{{(statusLabels[row.status]??row.status)+((row.activeCount??0)>1?' · '+row.activeCount:'')}}</span></div><p v-if="progress(row)" class="cq-muted" :title="progress(row)">{{progress(row)}}</p></Button>
  <div class="cq-row-meta"><div class="cq-metrics"><span class="cq-elapsed" title="从任务受理到结束，包含排队、执行及等待；不包含结果交付。">{{taskTime({...row,createdAt:row.jobCreatedAt},now)}}</span><span class="cq-heat">热度 {{row.heat}}</span><span>{{row.interactionCount}} 次交互</span><span>{{row.taskCount}} 个任务</span><span v-if="delivery(row)" class="cq-delivery">{{delivery(row)}}</span></div><time :title="'最近活动 · '+time(row.updatedAt)">{{time(row.updatedAt)}}</time><WorkerMenu v-if="writable&&!selectionMode" :row="row" :open="menu===sessionKey(row)" :deleting="deleting" :redact="redact" @update:open="emit('menu',$event?sessionKey(row):null)" @remove="emit('remove',$event)" @pick="emit('pick',$event)"/></div>
  <div v-if="row.tags.length" class="cq-tags"><span v-for="(tag,index) in row.tags.slice(0,2)" :key="index" :title="redact(tag)">{{redact(tag)}}</span><details v-if="row.tags.length>2" class="cq-disclosure cq-tag-disclosure" data-fold-key="tags"><summary>+{{row.tags.length-2}}</summary><div class="cq-expanded-tags"><span v-for="(tag,index) in row.tags.slice(2)" :key="index" :title="redact(tag)">{{redact(tag)}}</span></div></details></div>
 </article></div></component></template>
 <p v-if="!rows.length&&!loading&&!error" class="cq-muted">没有匹配的会话</p><Button v-if="list?.hasMore" variant="outline" :disabled="loading" @click="emit('more')">加载更多会话</Button>
</template>
